import { Fragment, useEffect } from "react";
import Breadcrumbs from "@components/breadcrumbs";
import { useSkin } from "@hooks/useSkin";
import { ChevronDown } from "react-feather";
import { columns } from "./datatable/columns";
import DataTable from "react-data-table-component";
import ProgressLoading from "../../../components/progress_loading";
import {
  UncontrolledAccordion,
  AccordionItem,
  AccordionHeader,
  AccordionBody,
  Card,
  Row,
  Col,
  Label,
  Input,
  Button,
} from "reactstrap";
import Select from "react-select";
import { selectThemeColors } from "@utils";
import CustomDatePicker from "../../../components/datepicker";
import ReactPaginate from "react-paginate";
import useInvoice from "../../../hooks/use_invoice";

const AllInvoices = () => {
  const { skin } = useSkin();
  const {
    getInvoices,
    generateInvoice,
    getInvoicesExport,
    invoiceList,
    filters,
    setFilters,
    invoicePaginates,
    setInvoicePaginates,
    invoiceLoadings,
  } = useInvoice();

  const handlePagination = (page) => {
    setInvoicePaginates({ ...invoicePaginates, current: page.selected });
    getInvoices(page.selected + 1, filters);
  };

  // ** Custom Pagination
  const CustomPagination = () => (
    <div className="d-flex align-items-center flex-row-reverse justify-content-between">
      <ReactPaginate
        previousLabel=""
        nextLabel=""
        forcePage={invoicePaginates.current - 1}
        onPageChange={(page) => handlePagination(page)}
        pageCount={invoicePaginates.total}
        breakLabel="..."
        pageRangeDisplayed={2}
        marginPagesDisplayed={2}
        activeClassName="active"
        pageClassName="page-item"
        breakClassName="page-item"
        nextLinkClassName="page-link"
        pageLinkClassName="page-link"
        breakLinkClassName="page-link"
        previousLinkClassName="page-link"
        nextClassName="page-item next-item"
        previousClassName="page-item prev-item"
        containerClassName="pagination react-paginate separated-pagination pagination-sm justify-content-end pe-1 mt-1"
      />
      <Button
        onClick={() => getInvoicesExport(filters)}
        disabled={invoiceLoadings.getInvoicesExport}
        color="success"
      >
        {invoiceLoadings.getInvoicesExport ? "Downloading..." : "Export Data"}
      </Button>
    </div>
  );

  useEffect(() => {
    setInvoicePaginates({ ...invoicePaginates, current: 1 });
    getInvoices(1, filters);
  }, []);

  return (
    <Fragment>
      <Breadcrumbs
        title="Invoices List"
        data={[{ title: "Invoice" }, { title: "Invoices List" }]}
      />
      {/* filterbar */}
      <Card>
        <UncontrolledAccordion>
          <AccordionItem>
            <AccordionHeader targetId="1">Filters</AccordionHeader>
            <AccordionBody accordionId="1">
              <Row>
                {/* created_at_gt */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="created_at_gt">Start Date</Label>
                  <CustomDatePicker
                    value={filters.created_at_gt}
                    onChange={(value) =>
                      setFilters({ ...filters, created_at_gt: value })
                    }
                    inputPlaceholder="select date"
                    calendarPopperPosition={"bottom"}
                  />
                </Col>
                {/* created_at_lt */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="created_at_lt">End Date</Label>
                  <CustomDatePicker
                    value={filters.created_at_lt}
                    onChange={(value) =>
                      setFilters({ ...filters, created_at_lt: value })
                    }
                    inputPlaceholder="select date"
                    calendarPopperPosition={"bottom"}
                  />
                </Col>
                {/* imsi */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="imsi">imsi</Label>
                  <Input
                    value={filters.imsi}
                    onChange={(e) =>
                      setFilters({ ...filters, imsi: e.target.value })
                    }
                    name="imsi"
                    id="imsi"
                  />
                </Col>
                {/* status */}
                <Col xs="12" sm="6" md="3" className={"mb-1"}>
                  <Label for="status">Status</Label>
                  <Select
                    isClearable={false}
                    theme={selectThemeColors}
                    closeMenuOnSelect={true}
                    placeholder="select option"
                    maxMenuHeight={120}
                    options={[
                      { label: "pending", value: "pending" },
                      { label: "paid", value: "paid" },
                    ]}
                    className={`react-select`}
                    classNamePrefix="select"
                    id="status"
                    name="status"
                    value={filters.status}
                    onChange={(value) =>
                      setFilters({ ...filters, status: value })
                    }
                  />
                </Col>
                {/* actions */}
                <Col xs="12" className={"d-flex justify-content-end"}>
                  <Button
                    style={{ marginRight: "auto" }}
                    onClick={generateInvoice}
                    disabled={invoiceLoadings.generateInvoice}
                    color="warning"
                  >
                    {invoiceLoadings.generateInvoice
                      ? "Generating..."
                      : "Generate Invoices"}
                  </Button>
                  <Button
                    style={{ marginRight: 8 }}
                    color="danger"
                    onClick={() => {
                      setInvoicePaginates({ ...invoicePaginates, current: 1 });
                      getInvoices(1, {
                        created_at_gt: null,
                        created_at_lt: null,
                        imsi: "",
                        status: null,
                      });
                      setFilters({
                        created_at_gt: null,
                        created_at_lt: null,
                        imsi: "",
                        status: null,
                      });
                    }}
                  >
                    Clear
                  </Button>
                  <Button
                    onClick={() => {
                      setInvoicePaginates({ ...invoicePaginates, current: 1 });
                      getInvoices(1, filters);
                    }}
                    style={{ width: 150 }}
                    color="primary"
                  >
                    Filter
                  </Button>
                </Col>
              </Row>
            </AccordionBody>
          </AccordionItem>
        </UncontrolledAccordion>
      </Card>
      {/* datatable */}
      <div className="react-dataTable mv_datatable_container">
        <DataTable
          noDataComponent={
            invoiceLoadings.getInvoices ? (
              ""
            ) : (
              <div style={{ margin: "24px 0" }}>No Invoice Founded!</div>
            )
          }
          noHeader
          pagination
          columns={columns}
          paginationPerPage={invoicePaginates.per_page}
          className="react-dataTable"
          sortIcon={<ChevronDown size={10} />}
          paginationComponent={CustomPagination}
          data={invoiceList}
          theme={skin === "dark" ? "darkTheme" : ""}
        />
        {invoiceLoadings.getInvoices ? (
          <div className="datatable_loading_cover">
            <ProgressLoading />
          </div>
        ) : null}
      </div>
    </Fragment>
  );
};
export default AllInvoices;
