import { useState } from "react";
import useHttp from "./use_http";
import toast from "react-hot-toast";
import moment from "moment";

const useInvoice = () => {
  const { httpService } = useHttp();
  const [invoiceLoadings, setInvoiceLoadings] = useState({
    getInvoices: false,
    generateInvoice: false,
    getInvoicesExport: false,
  });
  const [invoicePaginates, setInvoicePaginates] = useState({
    current: 1,
    total: 1,
    per_page: 10,
  });

  const [filters, setFilters] = useState({
    created_at_gt: null,
    created_at_lt: null,
    imsi: "",
    status: null,
  });

  const [invoiceList, setInvoiceList] = useState([]);

  const getInvoices = async (page, filtersData) => {
    const paramsData = {
      page: page,
    };
    if (filtersData.created_at_gt) {
      paramsData[
        "created_at_gt"
      ] = `${filtersData?.created_at_gt?.year}-${filtersData?.created_at_gt?.month}-${filtersData?.created_at_gt?.day}T00:00:00Z`;
    }
    if (filtersData.created_at_lt) {
      paramsData[
        "created_at_lt"
      ] = `${filtersData?.created_at_lt?.year}-${filtersData?.created_at_lt?.month}-${filtersData?.created_at_lt?.day}T23:59:59Z`;
    }
    if (filtersData.imsi.length > 0) {
      paramsData["imsi"] = filtersData.imsi;
    }
    if (filtersData.status) {
      paramsData["status"] = filtersData?.status?.value;
    }

    try {
      setInvoiceLoadings({ ...invoiceLoadings, getInvoices: true });
      const response = await httpService.get(`/v1/invoices`, {
        params: paramsData,
      });
      setInvoiceLoadings({ ...invoiceLoadings, getInvoices: false });
      setInvoicePaginates({
        ...invoicePaginates,
        current: response.data.meta.page,
        total: response.data.meta.pages,
        per_page: response.data.meta.limit,
      });
      if (response.data.data) {
        setInvoiceList(response.data.data);
      } else {
        setInvoiceList([]);
      }
    } catch ({ err, response }) {
      setInvoiceLoadings({ ...invoiceLoadings, getInvoices: false });
    }
  };

  const generateInvoice = async () => {
    try {
      setInvoiceLoadings({ ...invoiceLoadings, generateInvoice: true });
      const response = await httpService.post("/v1/invoices");
      setInvoiceLoadings({ ...invoiceLoadings, generateInvoice: false });
      toast.success(response.data.data);
      setFilters({
        created_at_gt: null,
        created_at_lt: null,
        imsi: "",
        status: null,
      });
      setInvoicePaginates({ ...invoicePaginates, current: 1 });
      getInvoices(1, {
        created_at_gt: null,
        created_at_lt: null,
        imsi: "",
        status: null,
      });
    } catch ({ err, response }) {
      setInvoiceLoadings({ ...invoiceLoadings, generateInvoice: false });
    }
  };

  const getInvoicesExport = async (filtersData) => {
    const paramsData = {};
    if (filtersData.created_at_gt) {
      paramsData[
        "created_at_gt"
      ] = `${filtersData?.created_at_gt?.year}-${filtersData?.created_at_gt?.month}-${filtersData?.created_at_gt?.day}T00:00:00Z`;
    }
    if (filtersData.created_at_lt) {
      paramsData[
        "created_at_lt"
      ] = `${filtersData?.created_at_lt?.year}-${filtersData?.created_at_lt?.month}-${filtersData?.created_at_lt?.day}T23:59:59Z`;
    }
    if (filtersData.imsi.length > 0) {
      paramsData["imsi"] = filtersData.imsi;
    }
    if (filtersData.status) {
      paramsData["status"] = filtersData?.status?.value;
    }

    try {
      setInvoiceLoadings({ ...invoiceLoadings, getInvoicesExport: true });
      const response = await httpService.get(`/v1/invoices/export`, {
        params: paramsData,
      });
      setInvoiceLoadings({ ...invoiceLoadings, getInvoicesExport: false });
      // Create a blob from the response
      const blob = new Blob([response.data], { type: "text/csv" });

      // Create a download link
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;

      // Define the file name for download
      link.setAttribute(
        "download",
        `invoices_export_${moment().format("YYYY-MM-DD")}.csv`
      );
      // Append link to body, click it, and remove it
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch ({ err, response }) {
      setInvoiceLoadings({ ...invoiceLoadings, getInvoicesExport: false });
    }
  };

  const exports = {
    getInvoices,
    generateInvoice,
    getInvoicesExport,
    invoiceList,
    filters,
    setFilters,
    invoicePaginates,
    setInvoicePaginates,
    invoiceLoadings,
  };
  return exports;
};
export default useInvoice;
