import moment from "moment/moment";
import formatHelper from "../../../../helper/format_helper";
import { BalanceFormatter } from "../../../../helper/balance_formatter";

export const columns = [
  {
    name: "IMSI",
    minWidth: "110px",
    maxWidth: "110px",
    selector: (row) => row.IMSI,
  },
  {
    name: "StartTime",
    minWidth: "160px",
    maxWidth: "160px",
    selector: (row) => row.StartTime,
    cell: (row) => moment(row.StartTime).format("YYYY-MM-DD HH:mm:ss"),
  },
  {
    name: "EndTime",
    minWidth: "160px",
    maxWidth: "160px",
    selector: (row) => row.EndTime,
    cell: (row) => moment(row.EndTime).format("YYYY-MM-DD HH:mm:ss"),
  },
  {
    name: "InvoicePrice",
    minWidth: "170px",
    maxWidth: "170px",
    selector: (row) => row.InvoicePrice,
    cell: (row) =>
      formatHelper.numberSeperator(row.InvoicePrice.toFixed(2)) + " toman",
  },
  {
    name: "Status",
    minWidth: "120px",
    maxWidth: "120px",
    selector: (row) => row.Status,
    cell: (row) => {
      if (row.Status == "pending") {
        return (
          <div
            style={{
              padding: "4px 12px",
              borderRadius: "33px",
              color: "white",
              background: "orange",
            }}
          >
            {row.Status}
          </div>
        );
      } else {
        return (
          <div
            style={{
              padding: "4px 12px",
              borderRadius: "33px",
              color: "white",
              background: "green",
            }}
          >
            {row.Status}
          </div>
        );
      }
    },
  },
  {
    name: "CostDetails",
    minWidth: "600px",
    maxWidth: "600px",
    selector: (row) => row.CostDetails,
    cell: (row) => {
      if (row?.CostDetails) {
        if (Object.keys(row.CostDetails).length > 0) {
          return Object.keys(row.CostDetails).map((item, index) => (
            <div
              style={{
                marginRight: 8,
                borderRadius: 33,
                padding: "8px 16px",
                display: "flex",
                alignItems: "center",
                background: "rgba(220,220,220,.4)",
              }}
              key={index}
            >
              {item} :{" "}
              {row.CostDetails[item]
                ? BalanceFormatter({
                    type: item,
                    value: row.CostDetails[item],
                  })
                : " - "}
            </div>
          ));
        } else {
          return "";
        }
      } else {
        return "";
      }
    },
  },
];
