import { formatBytes } from "./format_unit";
import PN from "persian-number";

export const BalanceFormatter = (balance) => {
  if (balance.type == "monetary" || balance.Type == "monetary") {
    if (balance.value || balance.value == 0) {
      return PN.sliceNumber(balance.value.toFixed(2)) + " toman";
    } else if (balance.Value || balance.Value == 0) {
      return PN.sliceNumber(balance.Value.toFixed(2)) + " toman";
    } else if (balance.remaining || balance.remaining == 0) {
      return PN.sliceNumber(balance.remaining.toFixed(2)) + " toman";
    }
  }
  if (balance.type == "data" || balance.Type == "data") {
    if (balance.value) {
      return formatBytes(balance.value);
    } else if (balance.Value) {
      return formatBytes(balance.Value);
    } else if (balance.remaining) {
      return formatBytes(balance.remaining);
    }
  }
  if (
    balance.type == "voice" ||
    balance.Type == "voice" ||
    balance.type == "video" ||
    balance.Type == "video"
  ) {
    if (balance.value) {
      const totalHours = Math.floor(balance.value / 3600);
      const totalMinutes = Math.floor((balance.value % 3600) / 60);
      const totalSeconds = balance.value % 60;
      const hours = String(totalHours).padStart(2, "0");
      const minutes = String(totalMinutes).padStart(2, "0");
      const seconds = String(totalSeconds).padStart(2, "0");
      return `${hours}:${minutes}:${seconds}`;
    } else if (balance.Value) {
      const totalHours = Math.floor(balance.Value / 3600);
      const totalMinutes = Math.floor((balance.Value % 3600) / 60);
      const totalSeconds = balance.Value % 60;
      const hours = String(totalHours).padStart(2, "0");
      const minutes = String(totalMinutes).padStart(2, "0");
      const seconds = String(totalSeconds).padStart(2, "0");
      return `${hours}:${minutes}:${seconds}`;
    } else if (balance.remaining) {
      const totalHours = Math.floor(balance.remaining / 3600);
      const totalMinutes = Math.floor((balance.remaining % 3600) / 60);
      const totalSeconds = balance.remaining % 60;
      const hours = String(totalHours).padStart(2, "0");
      const minutes = String(totalMinutes).padStart(2, "0");
      const seconds = String(totalSeconds).padStart(2, "0");
      return `${hours}:${minutes}:${seconds}`;
    }
  }
};
